var a=[{title:`Perché combinare le due cose`,text:`L’allenamento di forza migliora forza e funzione muscolare, e l’attività aerobica sostiene la resistenza e la salute di cuore e polmoni. Le indicazioni di salute pubblica raccomandano entrambe. Farne solo una può lasciare indietro parti della tua forma, soprattutto quando i tuoi obiettivi di tutti i giorni comprendono forza, capacità di camminare e restare attivi a lungo.`},{title:`L’effetto di interferenza`,text:`Quantità molto grandi di lavoro di resistenza possono talvolta ridurre i miglioramenti di potenza esplosiva o di alcuni esiti di forza, rispetto al solo allenamento di forza. Le rassegne recenti, tuttavia, trovano che l’allenamento combinato in genere migliora insieme capacità aerobica e forza, e la maggior parte di chi si allena a livello amatoriale non perde alcuna vera crescita muscolare a causa di esso.`},{title:`Scegli un ordine pratico`,text:`Se la forza è la tua priorità, fai i sollevamenti impegnativi quando sei fresco e il cardio facile dopo. Se il condizionamento è il tuo obiettivo principale, fai prima l’importante lavoro di resistenza. Distanziare le sessioni dure di diverse ore o in giorni diversi può aiutare con la fatica, soprattutto nell’allenamento avanzato.`},{title:`Bilancia giorni duri e facili`,text:`Per esempio, fai due giorni di forza total body più due o tre camminate veloci e una sessione facoltativa di ciclismo moderato. Un atleta più esperto potrebbe dover programmare con attenzione corse dure e sessioni di forza per le gambe. Se prestazioni e recupero ne risentono, smetti di accumulare intervalli al massimo sopra ogni allenamento di gambe.`},{title:`Usare TrainUp`,text:`Il tuo obiettivo in Profilo (forma generale, forza o condizionamento) ti dice quale tipo di lavoro mettere per primo mentre ti alleni ancora in entrambi. Il cardio non rovina automaticamente i progressi di forza. Tieni d’occhio le ripetizioni che salti e il tuo sforzo medio nello Storico. Quando rigeneri il piano, diventa più facile se 2 dei tuoi ultimi 3 allenamenti sono stati molto duri (RPE 9 o più) o completati per meno del 60%.`}];var o=[{label:`Umbrella review 2026: allenamento concorrente di forza e resistenza`,url:`https://pubmed.ncbi.nlm.nih.gov/41762427/`},{label:`CDC: raccomandazioni sull’attività fisica per gli adulti`,url:`https://www.cdc.gov/physical-activity-basics/guidelines/adults.html`},{label:`Position stand ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var t={sections:a,sources:o};export{t as default,a as sections,o as sources};